1	import type { ReactNode } from "react";
2	
3	// Presentational helpers shared by the user list and the user detail page.
4	// Not a route — only page/layout/route filenames are routable — so this file
5	// is safe to sit inside app/admin/users/.
6	//
7	// Everything here mirrors the vocabulary already established in
8	// app/admin/page.tsx (rounded-xl hairline borders, text-sm, tabular-nums on
9	// every figure, monochrome except for status semantics) so the two pages read
10	// as one panel rather than two.
11	
12	export function formatUsd(micros: number, decimals = 2): string {
13	  return `$${(micros / 1_000_000).toFixed(decimals)}`;
14	}
15	
16	/** Whole-second UTC stamp, matching the recent-builds table on /admin. */
17	export function formatDateTime(d: Date): string {
18	  return d.toISOString().replace("T", " ").slice(0, 19);
19	}
20	
21	export function formatDate(d: Date): string {
22	  return d.toISOString().slice(0, 10);
23	}
24	
25	export function truncate(text: string, max = 60): string {
26	  return text.length > max ? `${text.slice(0, max)}…` : text;
27	}
28	
29	export function statusClass(status: string): string {
30	  if (status === "SUCCEEDED") return "text-emerald-600 dark:text-emerald-400";
31	  if (status === "FAILED") return "text-red-600 dark:text-red-400";
32	  return "text-black/40 dark:text-white/40";
33	}
34	
35	/**
36	 * CreditLedger.reason is free text and carries three different encodings —
37	 * plain words ("build", "signup_grant"), a Stripe session id, and the social
38	 * reward state machine (app/api/rewards/_lib.ts) whose reason string embeds an
39	 * identity HASH. Rendering those raw would put a 64-char hex blob in the
40	 * middle of a billing statement, so decode them into something a human can
41	 * scan. The raw string is still shown on hover via `title`.
42	 */
43	export function reasonLabel(reason: string): string {
44	  if (reason === "build") return "Build";
45	  if (reason === "signup_grant") return "Signup grant";
46	  if (reason.startsWith("stripe:")) return "Credit purchase";
47	  if (reason.startsWith("reward:")) {
48	    const parts = reason.split(":");
49	    const platform = parts[1] ?? "";
50	    const name = platform ? platform[0].toUpperCase() + platform.slice(1) : "Social";
51	    return parts[2] === "pending" ? `${name} reward (pending)` : `${name} reward`;
52	  }
53	  return reason.replace(/_/g, " ");
54	}
55	
56	export function StatTile({
57	  label,
58	  value,
59	  hint,
60	  tone,
61	}: {
62	  label: string;
63	  value: ReactNode;
64	  hint?: ReactNode;
65	  tone?: "warn";
66	}) {
67	  return (
68	    <div className="rounded-xl border border-black/10 p-4 dark:border-white/10">
69	      <div className="text-xs text-black/50 dark:text-white/50">{label}</div>
70	      <div
71	        className={`mt-1 text-xl font-semibold tabular-nums ${
72	          tone === "warn" ? "text-amber-600 dark:text-amber-500" : ""
73	        }`}
74	      >
75	        {value}
76	      </div>
77	      {hint ? <div className="mt-1 text-xs text-black/50 dark:text-white/50">{hint}</div> : null}
78	    </div>
79	  );
80	}
81	
82	export function Panel({
83	  title,
84	  subtitle,
85	  children,
86	}: {
87	  title: string;
88	  subtitle?: ReactNode;
89	  children: ReactNode;
90	}) {
91	  return (
92	    <section className="rounded-xl border border-black/10 p-5 dark:border-white/10">
93	      <h2 className="text-sm font-medium">{title}</h2>
94	      {subtitle ? (
95	        <p className="mt-0.5 text-xs text-black/50 dark:text-white/50">{subtitle}</p>
96	      ) : null}
97	      <div className="mt-4">{children}</div>
98	    </section>
99	  );
100	}
101	
102	export function Empty({ children }: { children: ReactNode }) {
103	  return (
104	    <div className="rounded-xl border border-dashed border-black/15 p-10 text-center text-sm text-black/60 dark:border-white/15 dark:text-white/60">
105	      {children}
106	    </div>
107	  );
108	}
109	
110	/** Scrolling wrapper + hairline frame used by every table on both pages. */
111	export function TableFrame({ children }: { children: ReactNode }) {
112	  return (
113	    <div className="overflow-x-auto rounded-xl border border-black/10 dark:border-white/10">
114	      <table className="w-full text-left text-sm">{children}</table>
115	    </div>
116	  );
117	}
118	
119	export function Th({
120	  children,
121	  align = "left",
122	}: {
123	  children: ReactNode;
124	  align?: "left" | "right";
125	}) {
126	  return (
127	    <th className={`px-4 py-2 font-medium ${align === "right" ? "text-right" : ""}`}>{children}</th>
128	  );
129	}
