import Link from "next/link";
import { notFound } from "next/navigation";
import { Prisma } from "@prisma/client";
import { db } from "@/lib/db";
import { getAdminUser } from "@/lib/auth";
import {
  Empty,
  Panel,
  StatTile,
  TableFrame,
  Th,
  formatDate,
  formatDateTime,
  severityClass,
  siteHost,
  truncate,
} from "./ui";

export const dynamic = "force-dynamic";

const PAGE_SIZE = 25;

// ── Caps ──────────────────────────────────────────────────────────────────
// Two of the views filter Project by an id set assembled from another table.
// Both sets are small by nature — a flagged site is the exception, a taken-down
// site more so — but "small by nature" is not a bound, and an unbounded IN ()
// list is how a page like this dies quietly a year from now. Each cap is
// surfaced in the UI when it actually bites, rather than silently truncating.
const FLAGGED_SITE_CAP = 2000;
const TAKEN_DOWN_CAP = 2000;

type View = "live" | "flagged" | "down";

const VIEWS: Record<View, { label: string; blurb: string }> = {
  live: {
    label: "Live",
    blurb: "Every project with publishedAt set — the sites currently resolving on *.kodely.site.",
  },
  flagged: {
    label: "Needs review",
    blurb: "Live sites carrying at least one moderation finding nobody has ruled on yet.",
  },
  down: {
    label: "Taken down",
    blurb:
      "Projects an operator took offline from this panel and which are still offline. Read out of AdminAuditLog — publishedAt alone cannot tell a takedown from a site that was never published.",
  },
};

function isView(v: unknown): v is View {
  return typeof v === "string" && v in VIEWS;
}

type SortKey = "recent" | "oldest" | "slug" | "updated";

/**
 * DATABASE-NATIVE sorts only, for the same reason app/admin/users/page.tsx
 * gives: finding count, file count and last build are all rolled up per PAGE
 * from other tables, so offering "sort by findings" would sort 25 arbitrary
 * rows and look like it had sorted the registry. The "Needs review" view is the
 * honest version of that request — it filters in the database instead.
 */
const SORTS: Record<SortKey, { label: string; orderBy: Prisma.ProjectOrderByWithRelationInput }> = {
  recent: { label: "Newest publish", orderBy: { publishedAt: "desc" } },
  oldest: { label: "Oldest publish", orderBy: { publishedAt: "asc" } },
  updated: { label: "Recently changed", orderBy: { updatedAt: "desc" } },
  slug: { label: "Slug", orderBy: { slug: "asc" } },
};

function isSortKey(v: unknown): v is SortKey {
  return typeof v === "string" && v in SORTS;
}

function first(v: string | string[] | undefined): string {
  if (Array.isArray(v)) return v[0] ?? "";
  return v ?? "";
}

function href(params: { q: string; view: View; sort: SortKey; page: number }): string {
  const sp = new URLSearchParams();
  if (params.q) sp.set("q", params.q);
  if (params.view !== "live") sp.set("view", params.view);
  if (params.sort !== "recent") sp.set("sort", params.sort);
  if (params.page > 1) sp.set("page", String(params.page));
  const qs = sp.toString();
  return qs ? `/admin/sites?${qs}` : "/admin/sites";
}

// ── Per-page rollups ──────────────────────────────────────────────────────
// Everything below is keyed by projectId and fetched for the CURRENT PAGE ONLY,
// in a fixed number of queries regardless of how many sites are on it. No query
// ever runs inside a loop over rows.

type FindingRollupRow = {
  projectId: string;
  total: number;
  high: number;
  medium: number;
  low: number;
  blocked: number;
  unreviewed: number;
  falsePositive: number;
  lastFindingAt: Date | null;
};

type RuleAccuracyRow = {
  rule: string;
  total: number;
  sites: number;
  high: number;
  medium: number;
  low: number;
  blocked: number;
  reviewed: number;
  truePositive: number;
  falsePositive: number;
};

type Rollup = {
  findings: FindingRollupRow | null;
  files: number;
  builds: number;
  lastBuildAt: Date | null;
  takenDownAt: Date | null;
};

export default async function AdminSitesPage({
  searchParams,
}: {
  searchParams: Promise<{ [key: string]: string | string[] | undefined }>;
}) {
  // Defense in depth — app/admin/layout.tsx is the primary gate, but a layout
  // is not an authorization boundary on its own (it does not re-render on every
  // navigation within the section). 404 rather than redirect, so a non-admin
  // learns nothing about this path. Same idiom as every other page here.
  if (!(await getAdminUser())) notFound();

  const sp = await searchParams;
  const q = first(sp.q).trim();
  const viewRaw = first(sp.view);
  const view: View = isView(viewRaw) ? viewRaw : "live";
  const sortRaw = first(sp.sort);
  const sort: SortKey = isSortKey(sortRaw) ? sortRaw : "recent";
  const pageRaw = Number.parseInt(first(sp.page), 10);
  const page = Number.isFinite(pageRaw) && pageRaw > 0 ? pageRaw : 1;

  // ── Whole-table figures, and the id sets the two filtered views need ─────
  // ModerationFinding has no relation to Project (see prisma/schema.prisma), so
  // "which sites are flagged" cannot be a join in the Project query — it is one
  // grouped read of the findings table, done once here, not once per row.
  const [liveCount, findingTotal, unreviewedTotal, flaggedGroups, takenDownRows] =
    await Promise.all([
      db.project.count({ where: { publishedAt: { not: null } } }),
      db.moderationFinding.count(),
      db.moderationFinding.count({ where: { reviewedAt: null } }),
      db.moderationFinding.groupBy({
        by: ["projectId"],
        where: { reviewedAt: null },
        orderBy: { projectId: "asc" },
        take: FLAGGED_SITE_CAP,
      }),
      // Takedown is not a column — clearing publishedAt is indistinguishable
      // from "never published". The audit row written alongside it is the only
      // record that a takedown happened, so this view reads from there.
      db.$queryRaw<{ targetId: string; takenDownAt: Date }[]>`
        SELECT a."targetId", MAX(a."createdAt") AS "takenDownAt"
        FROM "AdminAuditLog" a
        WHERE a."action" = 'site.taken_down' AND a."targetType" = 'project'
          AND a."targetId" IS NOT NULL
        GROUP BY a."targetId"
        ORDER BY MAX(a."createdAt") DESC
        LIMIT ${TAKEN_DOWN_CAP}`,
    ]);

  const flaggedIds = flaggedGroups.map((g) => g.projectId);
  const takenDownAt = new Map(takenDownRows.map((r) => [r.targetId, r.takenDownAt]));

  // Search is by the two things an abuse report actually gives you: the
  // subdomain, or the person who owns it. Raw project id is accepted too, for
  // pasting straight out of a log line.
  const search: Prisma.ProjectWhereInput[] = q
    ? [
        {
          OR: [
            { slug: { contains: q, mode: "insensitive" } },
            { name: { contains: q, mode: "insensitive" } },
            { user: { email: { contains: q, mode: "insensitive" } } },
            { id: q },
          ],
        },
      ]
    : [];

  const scope: Prisma.ProjectWhereInput =
    view === "down"
      ? { publishedAt: null, id: { in: [...takenDownAt.keys()] } }
      : view === "flagged"
        ? { publishedAt: { not: null }, id: { in: flaggedIds } }
        : { publishedAt: { not: null } };

  const where: Prisma.ProjectWhereInput = { ...scope, AND: search };

  // publishedAt is null in the "Taken down" view, so ordering by it there would
  // be ordering by nothing. Project.updatedAt is bumped by the takedown write
  // itself (@updatedAt), which makes it the closest database-native stand-in for
  // takedown recency; the exact audit timestamp is shown per row.
  const orderBy: Prisma.ProjectOrderByWithRelationInput[] =
    view === "down"
      ? [{ updatedAt: "desc" }, { id: "asc" }]
      : // `id` breaks ties so pagination is stable when timestamps collide.
        [SORTS[sort].orderBy, { id: "asc" }];

  const [total, projects] = await Promise.all([
    db.project.count({ where }),
    db.project.findMany({
      where,
      orderBy,
      skip: (page - 1) * PAGE_SIZE,
      take: PAGE_SIZE,
      select: {
        id: true,
        name: true,
        slug: true,
        createdAt: true,
        updatedAt: true,
        publishedAt: true,
        // A relation select, not a per-row lookup — Prisma resolves this for the
        // whole page in one additional statement.
        user: { select: { id: true, email: true } },
      },
    }),
  ]);

  const ids = projects.map((p) => p.id);

  // Three grouped reads for the page, in parallel. Not three per row.
  const [findingRows, buildRows, fileRows, ruleRows] = await Promise.all([
    ids.length
      ? db.$queryRaw<FindingRollupRow[]>`
          SELECT f."projectId",
                 COUNT(*)::int AS "total",
                 COUNT(*) FILTER (WHERE f."severity" = 'high')::int AS "high",
                 COUNT(*) FILTER (WHERE f."severity" = 'medium')::int AS "medium",
                 COUNT(*) FILTER (WHERE f."severity" = 'low')::int AS "low",
                 COUNT(*) FILTER (WHERE f."action" = 'blocked')::int AS "blocked",
                 COUNT(*) FILTER (WHERE f."reviewedAt" IS NULL)::int AS "unreviewed",
                 COUNT(*) FILTER (WHERE f."outcome" = 'false_positive')::int AS "falsePositive",
                 MAX(f."createdAt") AS "lastFindingAt"
          FROM "ModerationFinding" f
          WHERE f."projectId" IN (${Prisma.join(ids)})
          GROUP BY f."projectId"`
      : Promise.resolve([]),
    ids.length
      ? db.build.groupBy({
          by: ["projectId"],
          where: { projectId: { in: ids } },
          _count: { _all: true },
          _max: { createdAt: true },
        })
      : Promise.resolve([]),
    // The file count that matters on this page is what is actually SERVED:
    // published build output. Draft rows and the Vite source tree are neither
    // reachable at the subdomain nor relevant to a takedown decision.
    ids.length
      ? db.projectFile.groupBy({
          by: ["projectId"],
          where: { projectId: { in: ids }, published: true, kind: "build" },
          _count: { _all: true },
        })
      : Promise.resolve([]),
    // Whole-table, not per-page: this panel is about how good the RULES are,
    // which is not a property of whichever 25 sites you are looking at.
    db.$queryRaw<RuleAccuracyRow[]>`
      SELECT f."rule",
             COUNT(*)::int AS "total",
             COUNT(DISTINCT f."projectId")::int AS "sites",
             COUNT(*) FILTER (WHERE f."severity" = 'high')::int AS "high",
             COUNT(*) FILTER (WHERE f."severity" = 'medium')::int AS "medium",
             COUNT(*) FILTER (WHERE f."severity" = 'low')::int AS "low",
             COUNT(*) FILTER (WHERE f."action" = 'blocked')::int AS "blocked",
             COUNT(*) FILTER (WHERE f."reviewedAt" IS NOT NULL)::int AS "reviewed",
             COUNT(*) FILTER (WHERE f."outcome" = 'true_positive')::int AS "truePositive",
             COUNT(*) FILTER (WHERE f."outcome" = 'false_positive')::int AS "falsePositive"
      FROM "ModerationFinding" f
      GROUP BY f."rule"
      ORDER BY COUNT(*) DESC`,
  ]);

  const rollups = new Map<string, Rollup>(
    ids.map((id) => [
      id,
      { findings: null, files: 0, builds: 0, lastBuildAt: null, takenDownAt: takenDownAt.get(id) ?? null },
    ]),
  );
  for (const r of findingRows) {
    const p = rollups.get(r.projectId);
    if (p) p.findings = r;
  }
  for (const r of buildRows) {
    const p = rollups.get(r.projectId);
    if (!p) continue;
    p.builds = r._count._all;
    p.lastBuildAt = r._max.createdAt;
  }
  for (const r of fileRows) {
    const p = rollups.get(r.projectId);
    if (p) p.files = r._count._all;
  }

  const pageCount = Math.max(1, Math.ceil(total / PAGE_SIZE));
  const flaggedCapped = flaggedIds.length >= FLAGGED_SITE_CAP;
  const takenDownCapped = takenDownAt.size >= TAKEN_DOWN_CAP;

  return (
    <div className="mx-auto max-w-6xl px-6 py-10">
      <div className="mb-8">
        <Link
          href="/admin"
          className="text-xs text-black/50 underline-offset-4 hover:underline dark:text-white/50"
        >
          ← kodely admin
        </Link>
        <div className="mt-1 text-lg font-semibold tracking-tight">Published sites</div>
        <p className="text-sm text-black/60 dark:text-white/60">
          Everything currently reachable on <span className="font-mono text-xs">*.kodely.site</span>,
          what the abuse scanner flagged on it, and the one lever that takes it offline.
        </p>
      </div>

      {findingTotal === 0 ? (
        <div className="mb-6 rounded-xl border border-amber-500/40 bg-amber-500/5 p-5 text-sm">
          <h2 className="text-sm font-medium text-amber-700 dark:text-amber-500">
            The findings table is empty — that is not the same as &ldquo;no abuse&rdquo;
          </h2>
          <p className="mt-2 text-black/70 dark:text-white/70">
            Nothing has ever written a <span className="font-mono text-xs">ModerationFinding</span>{" "}
            row. <span className="font-mono text-xs">lib/moderation.ts</span> runs on every publish
            and <span className="font-mono text-xs">app/api/projects/[id]/publish/route.ts</span>{" "}
            still only <span className="font-mono text-xs">console.warn</span>s the sub-blocking
            findings, so they exist in the logs and nowhere else. Read an empty findings column below
            as <em>&ldquo;never recorded&rdquo;</em>, never as <em>&ldquo;came back clean&rdquo;</em>
            . Blocking (<span className="font-mono text-xs">high</span>) findings never reach this
            table at all, by construction: the publish is refused, so the site was never live.
          </p>
        </div>
      ) : null}

      <div className="mb-6 grid grid-cols-2 gap-4 sm:grid-cols-5">
        <StatTile label="Live sites" value={liveCount} hint="publishedAt is set" />
        <StatTile
          label="Sites needing review"
          value={flaggedIds.length}
          tone={flaggedIds.length > 0 ? "warn" : undefined}
          hint={flaggedCapped ? `capped at ${FLAGGED_SITE_CAP}` : "≥1 unruled finding"}
        />
        <StatTile label="Findings recorded" value={findingTotal} />
        <StatTile
          label="Unreviewed findings"
          value={unreviewedTotal}
          tone={unreviewedTotal > 0 ? "warn" : undefined}
        />
        <StatTile
          label="Taken down"
          value={takenDownAt.size}
          hint={takenDownCapped ? `capped at ${TAKEN_DOWN_CAP}` : "from the audit log"}
        />
      </div>

      <div className="mb-4 flex flex-wrap gap-2">
        {(Object.keys(VIEWS) as View[]).map((v) => (
          <Link
            key={v}
            href={href({ q, view: v, sort, page: 1 })}
            aria-current={v === view ? "page" : undefined}
            className={`rounded-xl border px-3 py-1.5 text-sm ${
              v === view
                ? "border-black/40 font-medium dark:border-white/40"
                : "border-black/10 text-black/60 hover:bg-black/5 dark:border-white/10 dark:text-white/60 dark:hover:bg-white/5"
            }`}
          >
            {VIEWS[v].label}
          </Link>
        ))}
      </div>
      <p className="mb-6 text-xs text-black/50 dark:text-white/50">{VIEWS[view].blurb}</p>

      <form method="get" action="/admin/sites" className="mb-6 flex flex-wrap items-center gap-2">
        {view !== "live" ? <input type="hidden" name="view" value={view} /> : null}
        <input
          type="search"
          name="q"
          defaultValue={q}
          placeholder="Search slug, owner email or project id"
          aria-label="Search published sites"
          className="w-full max-w-sm rounded-xl border border-black/10 bg-transparent px-3 py-2 text-sm outline-none placeholder:text-black/40 focus:border-black/30 dark:border-white/10 dark:placeholder:text-white/40 dark:focus:border-white/30"
        />
        <select
          name="sort"
          defaultValue={sort}
          aria-label="Sort sites"
          disabled={view === "down"}
          className="rounded-xl border border-black/10 bg-transparent px-3 py-2 text-sm outline-none disabled:opacity-40 dark:border-white/10"
        >
          {(Object.keys(SORTS) as SortKey[]).map((k) => (
            <option key={k} value={k}>
              {SORTS[k].label}
            </option>
          ))}
        </select>
        <button
          type="submit"
          className="rounded-xl border border-black/10 px-3 py-2 text-sm font-medium hover:bg-black/5 dark:border-white/10 dark:hover:bg-white/5"
        >
          Search
        </button>
        {q ? (
          <Link
            href={href({ q: "", view, sort, page: 1 })}
            className="text-sm text-black/50 underline-offset-4 hover:underline dark:text-white/50"
          >
            Clear
          </Link>
        ) : null}
      </form>

      {projects.length === 0 ? (
        <Empty>
          {q
            ? `No ${VIEWS[view].label.toLowerCase()} site matches “${truncate(q, 40)}”.`
            : view === "flagged"
              ? "Nothing is waiting on a review. With the findings table still unpopulated, this view will stay empty even if sites are being flagged at publish time."
              : view === "down"
                ? "No site has been taken down from this panel."
                : "No project has ever been published."}
        </Empty>
      ) : (
        <TableFrame>
          <thead>
            <tr className="border-b border-black/10 text-xs text-black/50 dark:border-white/10 dark:text-white/50">
              <Th>Slug</Th>
              <Th>Owner</Th>
              <Th>{view === "down" ? "Taken down" : "Published"}</Th>
              <Th>Last build</Th>
              <Th align="right">Files</Th>
              <Th>Findings</Th>
            </tr>
          </thead>
          <tbody className="divide-y divide-black/10 dark:divide-white/10">
            {projects.map((p) => {
              const r = rollups.get(p.id);
              const f = r?.findings ?? null;
              return (
                <tr key={p.id}>
                  <td className="max-w-xs px-4 py-2">
                    <Link
                      href={`/admin/sites/${p.id}`}
                      className="font-mono text-xs font-medium underline-offset-4 hover:underline"
                    >
                      {truncate(p.slug, 40)}
                    </Link>
                    <div className="text-xs text-black/50 dark:text-white/50">
                      {truncate(p.name, 40)}
                    </div>
                  </td>
                  <td className="max-w-[14rem] px-4 py-2">
                    <Link
                      href={`/admin/users/${p.user.id}`}
                      className="underline-offset-4 hover:underline"
                    >
                      {truncate(p.user.email, 34)}
                    </Link>
                  </td>
                  <td className="whitespace-nowrap px-4 py-2 tabular-nums">
                    {view === "down" ? (
                      r?.takenDownAt ? (
                        <span className="text-black/70 dark:text-white/70">
                          {formatDateTime(r.takenDownAt)}
                        </span>
                      ) : (
                        <span className="text-black/40 dark:text-white/40">—</span>
                      )
                    ) : p.publishedAt ? (
                      <span className="text-emerald-600 dark:text-emerald-400">
                        {formatDate(p.publishedAt)}
                      </span>
                    ) : (
                      <span className="text-black/40 dark:text-white/40">draft</span>
                    )}
                  </td>
                  <td className="whitespace-nowrap px-4 py-2 tabular-nums text-black/70 dark:text-white/70">
                    {r?.lastBuildAt ? (
                      <>
                        {formatDate(r.lastBuildAt)}
                        <span className="ml-2 text-xs text-black/40 dark:text-white/40">
                          {r.builds} total
                        </span>
                      </>
                    ) : (
                      <span className="text-black/40 dark:text-white/40">never</span>
                    )}
                  </td>
                  <td className="px-4 py-2 text-right tabular-nums text-black/70 dark:text-white/70">
                    {r?.files ?? 0}
                  </td>
                  <td className="whitespace-nowrap px-4 py-2">
                    {f === null ? (
                      <span className="text-black/30 dark:text-white/30">none recorded</span>
                    ) : (
                      <span className="tabular-nums">
                        {f.high > 0 ? (
                          <span className={`mr-2 font-medium ${severityClass("high")}`}>
                            {f.high} high
                          </span>
                        ) : null}
                        {f.medium > 0 ? (
                          <span className={`mr-2 ${severityClass("medium")}`}>{f.medium} med</span>
                        ) : null}
                        {f.low > 0 ? (
                          <span className={`mr-2 ${severityClass("low")}`}>{f.low} low</span>
                        ) : null}
                        {f.unreviewed > 0 ? (
                          <span className="text-xs font-medium text-amber-600 dark:text-amber-500">
                            {f.unreviewed} unreviewed
                          </span>
                        ) : (
                          <span className="text-xs text-emerald-600 dark:text-emerald-400">
                            all reviewed
                          </span>
                        )}
                      </span>
                    )}
                  </td>
                </tr>
              );
            })}
          </tbody>
        </TableFrame>
      )}

      <div className="mt-4 flex items-center justify-between text-sm">
        <span className="text-black/50 dark:text-white/50">
          {total === 0
            ? "0 sites"
            : `${(page - 1) * PAGE_SIZE + 1}–${Math.min(page * PAGE_SIZE, total)} of ${total}`}
        </span>
        <span className="flex gap-2">
          {page > 1 ? (
            <Link
              href={href({ q, view, sort, page: page - 1 })}
              className="rounded-xl border border-black/10 px-3 py-1.5 hover:bg-black/5 dark:border-white/10 dark:hover:bg-white/5"
            >
              Previous
            </Link>
          ) : null}
          {page < pageCount ? (
            <Link
              href={href({ q, view, sort, page: page + 1 })}
              className="rounded-xl border border-black/10 px-3 py-1.5 hover:bg-black/5 dark:border-white/10 dark:hover:bg-white/5"
            >
              Next
            </Link>
          ) : null}
        </span>
      </div>

      <div className="mt-8">
        <Panel
          title="Rule accuracy"
          subtitle={
            <>
              Every finding ever recorded, grouped by rule — not just this page. The false-positive
              column is the number that decides whether a <span className="font-mono">medium</span>{" "}
              rule can be promoted to blocking, and it only moves when someone rules on findings in
              the site detail pages.
            </>
          }
        >
          {ruleRows.length === 0 ? (
            <Empty>
              No findings have been recorded, so no rule has an accuracy yet. Until the publish route
              writes to this table, the false-positive rate stays unmeasurable and no rule can be
              promoted on evidence.
            </Empty>
          ) : (
            <TableFrame>
              <thead>
                <tr className="border-b border-black/10 text-xs text-black/50 dark:border-white/10 dark:text-white/50">
                  <Th>Rule</Th>
                  <Th align="right">Findings</Th>
                  <Th align="right">Sites</Th>
                  <Th>Severity mix</Th>
                  <Th align="right">Reviewed</Th>
                  <Th align="right">FP rate</Th>
                </tr>
              </thead>
              <tbody className="divide-y divide-black/10 dark:divide-white/10">
                {ruleRows.map((r) => {
                  const fpRate = r.reviewed === 0 ? null : (r.falsePositive / r.reviewed) * 100;
                  return (
                    <tr key={r.rule}>
                      <td className="max-w-sm px-4 py-2 font-mono text-xs">{r.rule}</td>
                      <td className="px-4 py-2 text-right tabular-nums text-black/70 dark:text-white/70">
                        {r.total}
                        {r.blocked > 0 ? (
                          <span className="ml-2 text-xs text-red-600 dark:text-red-400">
                            {r.blocked} blocked
                          </span>
                        ) : null}
                      </td>
                      <td className="px-4 py-2 text-right tabular-nums text-black/70 dark:text-white/70">
                        {r.sites}
                      </td>
                      <td className="whitespace-nowrap px-4 py-2 text-xs tabular-nums">
                        {r.high > 0 ? (
                          <span className={`mr-2 ${severityClass("high")}`}>{r.high} high</span>
                        ) : null}
                        {r.medium > 0 ? (
                          <span className={`mr-2 ${severityClass("medium")}`}>{r.medium} med</span>
                        ) : null}
                        {r.low > 0 ? (
                          <span className={severityClass("low")}>{r.low} low</span>
                        ) : null}
                      </td>
                      <td className="px-4 py-2 text-right tabular-nums text-black/70 dark:text-white/70">
                        {r.reviewed} / {r.total}
                      </td>
                      <td className="px-4 py-2 text-right tabular-nums">
                        {fpRate === null ? (
                          <span className="text-black/30 dark:text-white/30">—</span>
                        ) : (
                          <span
                            className={
                              fpRate >= 20
                                ? "font-medium text-amber-600 dark:text-amber-500"
                                : "text-black/70 dark:text-white/70"
                            }
                            title={`${r.falsePositive} false positive of ${r.reviewed} reviewed`}
                          >
                            {fpRate.toFixed(0)}%
                          </span>
                        )}
                      </td>
                    </tr>
                  );
                })}
              </tbody>
            </TableFrame>
          )}
        </Panel>
      </div>

      <p className="mt-6 text-xs text-black/50 dark:text-white/50">
        A site is live when, and only when, <span className="font-mono">Project.publishedAt</span> is
        set — <span className="font-mono">app/api/site/[slug]</span> 404s every path without it, and{" "}
        <span className="font-mono">proxy.ts</span> holds no state of its own. Files counts the
        published build output that is actually served, not the draft tree or the Vite sources. Site
        content itself is never rendered in this panel; the hostname on each detail page is the way
        to look at a site.{" "}
        {liveCount > 0 && findingTotal === 0
          ? `All ${liveCount} live site(s) show no findings because nothing writes them yet — see the note above.`
          : null}
      </p>
    </div>
  );
}

import Link from "next/link";
import { notFound } from "next/navigation";
import { db } from "@/lib/db";
import { getAdminUser } from "@/lib/auth";
import { reviewFinding } from "../actions";
import {
  Empty,
  Notice,
  Panel,
  RULE_NOTES,
  SeverityBadge,
  StatTile,
  TableFrame,
  Th,
  buttonClass,
  evidenceText,
  formatDateTime,
  outcomeClass,
  outcomeLabel,
  severityRank,
  siteHost,
  truncate,
} from "../ui";

export const dynamic = "force-dynamic";

// Bounded read. Findings accumulate per publish ATTEMPT, so a project that has
// been republished a hundred times can hold a lot of rows even though each
// individual scan is capped (MAX_FINDINGS_PER_RULE in lib/moderation.ts). The
// table says so when it is showing a truncated view.
const FINDINGS_LIMIT = 300;
const AUDIT_LIMIT = 25;

function first(v: string | string[] | undefined): string {
  if (Array.isArray(v)) return v[0] ?? "";
  return v ?? "";
}

function metaSummary(meta: unknown): string {
  if (meta === null || typeof meta !== "object" || Array.isArray(meta)) return "";
  return Object.entries(meta as Record<string, unknown>)
    .map(([k, v]) => `${k}=${typeof v === "string" ? v : JSON.stringify(v)}`)
    .join("  ·  ");
}

export default async function AdminSiteDetailPage({
  params,
  searchParams,
}: {
  params: Promise<{ id: string }>;
  searchParams: Promise<{ [key: string]: string | string[] | undefined }>;
}) {
  // Defense in depth — see app/admin/page.tsx. The layout gate is the primary
  // one, but a layout must not be the sole authorization boundary.
  if (!(await getAdminUser())) notFound();

  const { id } = await params;
  const flash = first((await searchParams).takedown);

  const project = await db.project.findUnique({
    where: { id },
    select: {
      id: true,
      name: true,
      slug: true,
      createdAt: true,
      updatedAt: true,
      publishedAt: true,
      user: { select: { id: true, email: true, name: true } },
    },
  });
  if (!project) notFound();

  const [findings, findingTotal, fileGroups, buildAgg, audit] = await Promise.all([
    db.moderationFinding.findMany({
      where: { projectId: id },
      // Served straight off @@index([projectId, createdAt]). Re-sorted below by
      // review state and severity, which are not index-ordered.
      orderBy: { createdAt: "desc" },
      take: FINDINGS_LIMIT,
    }),
    db.moderationFinding.count({ where: { projectId: id } }),
    // One grouped read covers all four file universes (draft/published ×
    // source/build) — see the ProjectFile comment in prisma/schema.prisma.
    db.projectFile.groupBy({
      by: ["published", "kind"],
      where: { projectId: id },
      _count: { _all: true },
    }),
    db.build.aggregate({
      where: { projectId: id },
      _count: { _all: true },
      _max: { createdAt: true },
    }),
    // Everything this panel has ever done to this project. The takedown writes
    // one of these in the same transaction as the unpublish, so this is the
    // only place a takedown is recorded as a takedown.
    db.adminAuditLog.findMany({
      where: { targetType: "project", targetId: id },
      orderBy: { createdAt: "desc" },
      take: AUDIT_LIMIT,
    }),
  ]);

  const servedFiles =
    fileGroups.find((g) => g.published && g.kind === "build")?._count._all ?? 0;
  const draftFiles = fileGroups.find((g) => !g.published && g.kind === "build")?._count._all ?? 0;
  const sourceFiles = fileGroups.find((g) => !g.published && g.kind === "source")?._count._all ?? 0;

  // Unreviewed first (this is a work queue), then worst severity, then newest.
  // `severity` is a free-text column, so ordering it in SQL would sort
  // alphabetically — "high, low, medium" — which is exactly backwards for the
  // middle two. The page-sized slice is already in memory, so sort it here.
  const sorted = [...findings].sort(
    (a, b) =>
      Number(a.reviewedAt !== null) - Number(b.reviewedAt !== null) ||
      severityRank(a.severity) - severityRank(b.severity) ||
      b.createdAt.getTime() - a.createdAt.getTime(),
  );

  const unreviewed = findings.filter((f) => f.reviewedAt === null).length;
  const high = findings.filter((f) => f.severity === "high").length;
  const blocked = findings.filter((f) => f.action === "blocked").length;
  const live = project.publishedAt !== null;
  const lastTakedown = audit.find((a) => a.action === "site.taken_down") ?? null;
  const host = siteHost(project.slug);

  return (
    <div className="mx-auto max-w-6xl px-6 py-10">
      <div className="mb-8">
        <Link
          href="/admin/sites"
          className="text-xs text-black/50 underline-offset-4 hover:underline dark:text-white/50"
        >
          ← Published sites
        </Link>
        <div className="mt-1 font-mono text-lg font-semibold tracking-tight">{project.slug}</div>
        <p className="text-sm text-black/60 dark:text-white/60">
          {truncate(project.name, 60)} · owned by{" "}
          <Link
            href={`/admin/users/${project.user.id}`}
            className="underline-offset-4 hover:underline"
          >
            {project.user.email}
          </Link>{" "}
          · created {formatDateTime(project.createdAt)}
        </p>
        <p className="mt-1 font-mono text-xs text-black/40 dark:text-white/40">{project.id}</p>
      </div>

      {flash === "done" ? (
        <div className="mb-6">
          <Notice tone="good" title="Site taken down">
            <span className="font-mono text-xs">{host}</span> now returns 404. The owner&apos;s
            project, draft tree and published files are all untouched — nothing was deleted. A cached
            copy can still answer for up to a minute; see the caveat below.
          </Notice>
        </div>
      ) : flash === "already" ? (
        <div className="mb-6">
          <Notice tone="warn" title="Nothing to do">
            This project was already offline when the takedown was submitted — most likely someone
            else got there first, or the owner never republished.
          </Notice>
        </div>
      ) : null}

      <div className="mb-8 grid grid-cols-2 gap-4 sm:grid-cols-3 lg:grid-cols-6">
        <StatTile
          label="Status"
          value={
            live ? (
              <span className="text-emerald-600 dark:text-emerald-400">Live</span>
            ) : (
              <span className="text-black/50 dark:text-white/50">Offline</span>
            )
          }
          hint={
            live
              ? `since ${formatDateTime(project.publishedAt as Date)}`
              : lastTakedown
                ? `taken down ${formatDateTime(lastTakedown.createdAt)}`
                : "never published, or unpublished elsewhere"
          }
        />
        <StatTile label="Findings" value={findingTotal} hint="all publish attempts" />
        <StatTile
          label="Unreviewed"
          value={unreviewed}
          tone={unreviewed > 0 ? "warn" : undefined}
          hint={findingTotal > findings.length ? `of the ${findings.length} shown` : "on this page"}
        />
        <StatTile
          label="High severity"
          value={high}
          tone={high > 0 ? "bad" : undefined}
          hint={blocked > 0 ? `${blocked} blocked a publish` : "none blocked a publish"}
        />
        <StatTile label="Files served" value={servedFiles} hint={`${draftFiles} draft build files`} />
        <StatTile
          label="Builds"
          value={buildAgg._count._all}
          hint={
            buildAgg._max.createdAt ? `last ${formatDateTime(buildAgg._max.createdAt)}` : "never built"
          }
        />
      </div>

      <div className="mb-8 grid gap-4 lg:grid-cols-2">
        <Panel
          title="The live site"
          subtitle="Reviewing means looking at the page itself. This panel never renders site content."
        >
          <div className="font-mono text-sm">{host}</div>
          {live ? (
            <a
              href={`https://${host}`}
              target="_blank"
              rel="noopener noreferrer nofollow"
              className={`mt-3 inline-block ${buttonClass()}`}
            >
              Open in a new tab ↗
            </a>
          ) : (
            <p className="mt-3 text-sm text-black/50 dark:text-white/50">
              Offline — this hostname currently 404s.
            </p>
          )}
          <p className="mt-3 text-xs text-black/50 dark:text-white/50">
            Only the public hostname is linked, never the internal{" "}
            <span className="font-mono">/api/site/{project.slug}</span> path. That route serves the
            customer&apos;s HTML under a{" "}
            <span className="font-mono">script-src &apos;self&apos; &apos;unsafe-inline&apos;</span>{" "}
            policy scoped to whatever origin answered — on a{" "}
            <span className="font-mono">*.kodely.site</span> subdomain that is an isolated origin, on
            the admin host it would not be.
          </p>
        </Panel>

        <Panel title="Owner" subtitle="Takedown affects the site, never the account or the work.">
          <div className="text-sm">
            <Link
              href={`/admin/users/${project.user.id}`}
              className="font-medium underline-offset-4 hover:underline"
            >
              {project.user.email}
            </Link>
            {project.user.name ? (
              <div className="text-xs text-black/50 dark:text-white/50">
                {truncate(project.user.name, 50)}
              </div>
            ) : null}
          </div>
          <ul className="mt-3 list-disc space-y-1 pl-5 text-xs text-black/60 dark:text-white/60">
            <li>
              {sourceFiles} source file(s) and {draftFiles} draft build file(s) in their working
              tree — a takedown touches none of them.
            </li>
            <li>
              The {servedFiles} published file(s) also stay in the database. Taking the site down
              clears <span className="font-mono">publishedAt</span> and nothing else.
            </li>
            <li>Nothing here notifies the owner. If they should hear about it, email them.</li>
          </ul>
        </Panel>
      </div>

      <div className="mb-8">
        <Panel
          title="Moderation findings"
          subtitle={
            <>
              What <span className="font-mono">lib/moderation.ts</span> flagged when this project was
              published. Ruling on each one is what makes the per-rule false-positive rate
              measurable, which is the thing currently standing between a{" "}
              <span className="font-mono">medium</span> rule and being promoted to blocking.
              {findingTotal > findings.length
                ? ` Showing the most recent ${findings.length} of ${findingTotal}.`
                : ""}
            </>
          }
        >
          {sorted.length === 0 ? (
            <Empty>
              No findings recorded for this project — which today means &ldquo;nothing has ever
              written one&rdquo;, not &ldquo;this site scanned clean&rdquo;. The publish route still
              only logs sub-blocking findings to the console.
            </Empty>
          ) : (
            <TableFrame>
              <thead>
                <tr className="border-b border-black/10 text-xs text-black/50 dark:border-white/10 dark:text-white/50">
                  <Th>Severity</Th>
                  <Th>Rule</Th>
                  <Th>Where</Th>
                  <Th>Evidence</Th>
                  <Th>Review</Th>
                </tr>
              </thead>
              <tbody className="divide-y divide-black/10 dark:divide-white/10">
                {sorted.map((f) => (
                  <tr key={f.id} className="align-top">
                    <td className="whitespace-nowrap px-4 py-3">
                      <SeverityBadge severity={f.severity} />
                      <div className="mt-1 text-xs text-black/50 dark:text-white/50">
                        {f.action === "blocked" ? "blocked the publish" : "recorded"}
                      </div>
                    </td>
                    <td className="max-w-xs px-4 py-3">
                      <div className="font-mono text-xs font-medium">{f.rule}</div>
                      <div className="mt-1 text-xs text-black/55 dark:text-white/55">
                        {RULE_NOTES[f.rule] ?? "No description on file for this rule id."}
                      </div>
                    </td>
                    <td className="max-w-[12rem] px-4 py-3">
                      <div className="break-all font-mono text-xs text-black/70 dark:text-white/70">
                        {truncate(f.path, 46)}
                      </div>
                      <div className="mt-1 whitespace-nowrap text-xs tabular-nums text-black/40 dark:text-white/40">
                        {formatDateTime(f.createdAt)}
                      </div>
                    </td>
                    <td className="max-w-sm px-4 py-3">
                      {/* Truncated on purpose and never expandable — this is a
                          snippet of someone else's private work. */}
                      <code className="block break-all text-xs text-black/60 dark:text-white/60">
                        {evidenceText(f.evidence)}
                      </code>
                    </td>
                    <td className="whitespace-nowrap px-4 py-3">
                      <div className={`text-xs font-medium ${outcomeClass(f.outcome)}`}>
                        {outcomeLabel(f.outcome)}
                      </div>
                      {f.reviewedAt ? (
                        <div className="mt-0.5 text-xs text-black/40 dark:text-white/40">
                          {truncate(f.reviewedBy ?? "unknown", 28)}
                          <br />
                          <span className="tabular-nums">{formatDateTime(f.reviewedAt)}</span>
                        </div>
                      ) : null}
                      <form action={reviewFinding} className="mt-2 flex gap-1.5">
                        <input type="hidden" name="findingId" value={f.id} />
                        <button
                          type="submit"
                          name="outcome"
                          value="true_positive"
                          className="rounded-lg border border-black/10 px-2 py-1 text-xs hover:bg-black/5 dark:border-white/10 dark:hover:bg-white/5"
                        >
                          True
                        </button>
                        <button
                          type="submit"
                          name="outcome"
                          value="false_positive"
                          className="rounded-lg border border-black/10 px-2 py-1 text-xs hover:bg-black/5 dark:border-white/10 dark:hover:bg-white/5"
                        >
                          False
                        </button>
                      </form>
                    </td>
                  </tr>
                ))}
              </tbody>
            </TableFrame>
          )}
        </Panel>
      </div>

      <div className="mb-8">
        {live ? (
          <div className="rounded-xl border border-red-500/40 bg-red-500/5 p-5">
            <h2 className="text-sm font-medium text-red-700 dark:text-red-400">Take this site offline</h2>
            <p className="mt-2 text-sm text-black/70 dark:text-white/70">
              Clears <span className="font-mono">publishedAt</span>, which is the single thing that
              makes <span className="font-mono">{host}</span> resolve. The owner keeps their project,
              their draft, their published files and their slug, and can republish it themselves at
              any time. There is a confirmation step on the next page.
            </p>
            <Link href={`/admin/sites/${project.id}/takedown`} className={`mt-4 inline-block ${buttonClass("bad")}`}>
              Take down…
            </Link>
          </div>
        ) : (
          <Notice
            title="This site is offline"
            tone="neutral"
          >
            <span className="font-mono text-xs">{host}</span> returns 404.{" "}
            {lastTakedown
              ? `Taken down by ${lastTakedown.actorEmail} on ${formatDateTime(lastTakedown.createdAt)}.`
              : "There is no takedown in the audit log for it, so it was never published or was unpublished by something outside this panel."}{" "}
            The owner can put it back by publishing again from their project page — which re-runs the
            secret scan and the moderation gate, so anything rated{" "}
            <span className="font-mono">high</span> will refuse the republish on its own.
          </Notice>
        )}
      </div>

      <Panel
        title="Admin actions on this project"
        subtitle={
          audit.length >= AUDIT_LIMIT
            ? `Most recent ${AUDIT_LIMIT} entries from AdminAuditLog, newest first.`
            : "Every entry AdminAuditLog holds for this project, newest first."
        }
      >
        {audit.length === 0 ? (
          <Empty>No admin action has ever been recorded against this project.</Empty>
        ) : (
          <ol className="space-y-1.5">
            {audit.map((a) => (
              <li key={a.id} className="flex flex-wrap items-baseline gap-x-3 text-sm">
                <span className="w-40 shrink-0 tabular-nums text-xs text-black/50 dark:text-white/50">
                  {formatDateTime(a.createdAt)}
                </span>
                <span className="font-medium">{a.action}</span>
                <span className="text-xs text-black/50 dark:text-white/50">
                  {truncate(a.actorEmail, 40)}
                </span>
                <span className="text-xs text-black/40 dark:text-white/40">
                  {truncate(metaSummary(a.meta), 90)}
                </span>
              </li>
            ))}
          </ol>
        )}
      </Panel>
    </div>
  );
}

import Link from "next/link";
import { notFound } from "next/navigation";
import { db } from "@/lib/db";
import { getAdminUser } from "@/lib/auth";
import { takeDownSite } from "../../actions";
import {
  Notice,
  TAKEDOWN_REASONS,
  buttonClass,
  formatDateTime,
  siteHost,
  truncate,
} from "../../ui";

export const dynamic = "force-dynamic";

function first(v: string | string[] | undefined): string {
  if (Array.isArray(v)) return v[0] ?? "";
  return v ?? "";
}

export default async function AdminSiteTakedownPage({
  params,
  searchParams,
}: {
  params: Promise<{ id: string }>;
  searchParams: Promise<{ [key: string]: string | string[] | undefined }>;
}) {
  // Defense in depth — see app/admin/page.tsx. The action behind this form
  // re-checks the same thing, because a Server Function is reachable by direct
  // POST without this page ever rendering.
  if (!(await getAdminUser())) notFound();

  const { id } = await params;
  const error = first((await searchParams).error);

  const project = await db.project.findUnique({
    where: { id },
    select: {
      id: true,
      name: true,
      slug: true,
      publishedAt: true,
      user: { select: { id: true, email: true } },
    },
  });
  if (!project) notFound();

  const [servedFiles, unreviewed, findingTotal] = await Promise.all([
    db.projectFile.count({ where: { projectId: id, published: true, kind: "build" } }),
    db.moderationFinding.count({ where: { projectId: id, reviewedAt: null } }),
    db.moderationFinding.count({ where: { projectId: id } }),
  ]);

  const host = siteHost(project.slug);

  return (
    <div className="mx-auto max-w-3xl px-6 py-10">
      <div className="mb-8">
        <Link
          href={`/admin/sites/${project.id}`}
          className="text-xs text-black/50 underline-offset-4 hover:underline dark:text-white/50"
        >
          ← {truncate(project.slug, 40)}
        </Link>
        <div className="mt-1 text-lg font-semibold tracking-tight">Take this site offline</div>
        <p className="text-sm text-black/60 dark:text-white/60">
          <span className="font-mono text-xs">{host}</span> · {truncate(project.name, 44)} ·{" "}
          <Link
            href={`/admin/users/${project.user.id}`}
            className="underline-offset-4 hover:underline"
          >
            {project.user.email}
          </Link>
        </p>
      </div>

      {project.publishedAt === null ? (
        <>
          <Notice title="Already offline" tone="neutral">
            <span className="font-mono text-xs">{host}</span> is not resolving —{" "}
            <span className="font-mono">publishedAt</span> is already null. There is nothing to take
            down.
          </Notice>
          <Link href={`/admin/sites/${project.id}`} className={`mt-6 inline-block ${buttonClass()}`}>
            Back to the site
          </Link>
        </>
      ) : (
        <>
          <div className="mb-6 rounded-xl border border-black/10 p-5 text-sm dark:border-white/10">
            <h2 className="text-sm font-medium">What this does, exactly</h2>
            <ul className="mt-2 list-disc space-y-2 pl-5 text-black/70 dark:text-white/70">
              <li>
                Sets <span className="font-mono">Project.publishedAt</span> to null. That is the only
                write.{" "}
                <span className="font-mono">app/api/site/[slug]/[[...path]]</span> answers 404 to
                every path once it is null — pages, assets, and the synthesised{" "}
                <span className="font-mono">robots.txt</span> and{" "}
                <span className="font-mono">sitemap.xml</span> alike.
              </li>
              <li>
                <strong>Nothing is deleted.</strong> The {servedFiles} published file(s) stay in the
                database, the owner&apos;s draft tree and Vite sources are untouched, the project
                keeps its name and its slug, and the account is not affected in any way.
              </li>
              <li>
                <strong>The owner can put it back.</strong> Publishing again from their project page
                republishes the same slug. That republish re-runs the secret scan and the moderation
                gate, so a <span className="font-mono">high</span>-severity finding will refuse it on
                its own — but nothing here bars them from trying.
              </li>
              <li>
                It also counts as a new publish against their 24-hour publish rate limit
                (<span className="font-mono">lib/rate-limit.ts</span>), because the limit counts
                projects with a recent <span className="font-mono">publishedAt</span> and this
                clears theirs.
              </li>
              <li>
                <strong>The owner is not notified.</strong> Nothing emails them and nothing on their
                dashboard explains why; the project simply shows as unpublished again. If they should
                hear about it, that is a separate message you send.
              </li>
            </ul>
          </div>

          <div className="mb-6 rounded-xl border border-amber-500/40 bg-amber-500/5 p-5 text-sm">
            <h2 className="text-sm font-medium text-amber-700 dark:text-amber-500">
              Not instant — a cached copy can survive about a minute
            </h2>
            <p className="mt-2 text-black/70 dark:text-white/70">
              Every response from the site route carries{" "}
              <span className="font-mono text-xs">Cache-Control: public, max-age=60</span>. A browser
              or any intermediary cache that already fetched a page may keep serving its stored copy
              for up to 60 seconds after this write, and nothing here issues a purge. A tab that is
              already open keeps whatever it has until it is reloaded. For a live phishing page being
              actively driven by traffic, treat the takedown as effective within a minute, not on the
              click — and say so if you are answering an abuse report with a timestamp.
            </p>
          </div>

          {findingTotal > 0 && unreviewed > 0 ? (
            <div className="mb-6">
              <Notice tone="warn" title={`${unreviewed} finding(s) on this site are still unruled`}>
                Marking them true or false positive before you take the site down is what turns this
                takedown into a data point about the rules rather than just an outcome.
              </Notice>
            </div>
          ) : null}

          {error === "slug" ? (
            <div className="mb-6">
              <Notice tone="bad" title="That did not match">
                The confirmation text has to be the slug exactly:{" "}
                <span className="font-mono">{project.slug}</span>. Nothing was changed.
              </Notice>
            </div>
          ) : error === "reason" ? (
            <div className="mb-6">
              <Notice tone="bad" title="Pick a reason">
                A takedown has to say why — it is what the audit log records. Nothing was changed.
              </Notice>
            </div>
          ) : null}

          <form
            action={takeDownSite}
            className="rounded-xl border border-red-500/40 bg-red-500/5 p-5"
          >
            <input type="hidden" name="projectId" value={project.id} />

            <label htmlFor="reason" className="block text-sm font-medium">
              Why
            </label>
            <p className="mt-0.5 text-xs text-black/50 dark:text-white/50">
              Recorded in <span className="font-mono">AdminAuditLog</span>. A closed list on purpose
              — that log is documented as non-PII context, so the reporter&apos;s details and the
              narrative belong in the report thread, not here.
            </p>
            <select
              id="reason"
              name="reason"
              required
              defaultValue=""
              className="mt-2 w-full max-w-sm rounded-xl border border-black/10 bg-transparent px-3 py-2 text-sm outline-none focus:border-black/30 dark:border-white/10 dark:focus:border-white/30"
            >
              <option value="" disabled>
                Choose a reason…
              </option>
              {Object.entries(TAKEDOWN_REASONS).map(([value, label]) => (
                <option key={value} value={value}>
                  {label}
                </option>
              ))}
            </select>

            <label htmlFor="confirmSlug" className="mt-6 block text-sm font-medium">
              Type <span className="font-mono">{project.slug}</span> to confirm
            </label>
            <p className="mt-0.5 text-xs text-black/50 dark:text-white/50">
              Checked on the server, not just here. Published since{" "}
              {formatDateTime(project.publishedAt)}.
            </p>
            <input
              id="confirmSlug"
              name="confirmSlug"
              type="text"
              required
              autoComplete="off"
              spellCheck={false}
              placeholder={project.slug}
              aria-label={`Type ${project.slug} to confirm takedown`}
              className="mt-2 w-full max-w-sm rounded-xl border border-black/10 bg-transparent px-3 py-2 font-mono text-sm outline-none placeholder:text-black/25 focus:border-black/30 dark:border-white/10 dark:placeholder:text-white/25 dark:focus:border-white/30"
            />

            <div className="mt-6 flex flex-wrap items-center gap-3">
              <button type="submit" className={buttonClass("bad")}>
                Take {project.slug} offline
              </button>
              <Link
                href={`/admin/sites/${project.id}`}
                className="text-sm text-black/50 underline-offset-4 hover:underline dark:text-white/50"
              >
                Cancel
              </Link>
            </div>
          </form>

          <p className="mt-6 text-xs text-black/50 dark:text-white/50">
            This panel has no delete. Removing a project outright is the owner&apos;s action, from
            their own dashboard.
          </p>
        </>
      )}
    </div>
  );
}

